def transform(grid):
    n = len(grid); m = len(grid[0])
    cells = [(r, c, grid[r][c]) for r in range(n) for c in range(m) if grid[r][c]]
    best = None
    for name, fn in (('m', lambda r, c: c - r), ('p', lambda r, c: c + r)):
        groups = {}
        for r, c, v in cells:
            groups.setdefault(fn(r, c), set()).add(v)
        if all(len(s) == 1 for s in groups.values()):
            k = len(groups)
            if best is None or k < best[0]:
                best = (k, fn, groups)
    k, fn, groups = best
    consts = sorted(groups)
    P = len(consts); mn = consts[0]
    seq = {}
    for c0 in consts:
        seq[(c0 - mn) % P] = next(iter(groups[c0]))
    return [[seq.get((fn(r, c) - mn) % P, 0) for c in range(m)] for r in range(n)]
